SVGS = ['<svg viewBox="0 0 700 235" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="235" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TÜRK DÜNYASININ ORTAK KÜLTÜRÜNÜ OLUŞTURAN DÖRT TEMEL UNSUR</text>\n  <rect x="20" y="44" width="152" height="172" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="96" y="68" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">1. DİL VE EDEBİYAT</text>\n  <text x="96" y="90" text-anchor="middle" font-size="9" fill="#334155">• Orhun Abideleri</text>\n  <text x="96" y="108" text-anchor="middle" font-size="9" fill="#334155">• Dîvânu Lugâti\'t-Türk</text>\n  <text x="96" y="126" text-anchor="middle" font-size="9" fill="#334155">• Dede Korkut ve Manas</text>\n  <text x="96" y="144" text-anchor="middle" font-size="9" fill="#334155">• Atasözleri (Savlar)</text>\n  <text x="96" y="164" text-anchor="middle" font-size="9" font-weight="bold" fill="#1d4ed8">• Cengiz Aytmatov, Vahapzade</text>\n  <rect x="188" y="44" width="152" height="172" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="264" y="68" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">2. İNANÇ VE HİKMET</text>\n  <text x="264" y="90" text-anchor="middle" font-size="9" fill="#334155">• Hoca Ahmet Yesevî</text>\n  <text x="264" y="108" text-anchor="middle" font-size="9" fill="#334155">(Dîvân-ı Hikmet)</text>\n  <text x="264" y="126" text-anchor="middle" font-size="9" fill="#334155">• Yunus Emre ve Mevlânâ</text>\n  <text x="264" y="144" text-anchor="middle" font-size="9" fill="#334155">• Adalet, vatanseverlik,</text>\n  <text x="264" y="164" text-anchor="middle" font-size="9" font-weight="bold" fill="#15803d">büyüklere saygı ve hoşgörü</text>\n  <rect x="356" y="44" width="152" height="172" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="432" y="68" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">3. COĞRAFYA VE GELENEK</text>\n  <text x="432" y="90" text-anchor="middle" font-size="9" fill="#334155">• Ötüken, Altaylar, Tanrı</text>\n  <text x="432" y="108" text-anchor="middle" font-size="9" fill="#334155">Dağları, Türkistan, Anadolu</text>\n  <text x="432" y="126" text-anchor="middle" font-size="9" fill="#334155">• İpek Yolu kervansarayları</text>\n  <text x="432" y="144" text-anchor="middle" font-size="9" fill="#334155">• Nevruz (Ergenekon/Bahar)</text>\n  <text x="432" y="164" text-anchor="middle" font-size="9" font-weight="bold" fill="#b45309">• Misafirperverlik ve toy</text>\n  <rect x="524" y="44" width="156" height="172" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="602" y="68" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">4. SANAT VE MUSİKİ</text>\n  <text x="602" y="90" text-anchor="middle" font-size="9" fill="#334155">• Halı-kilim motifleri (pazırık,</text>\n  <text x="602" y="108" text-anchor="middle" font-size="9" fill="#334155">hayat ağacı, koçboynuzu)</text>\n  <text x="602" y="126" text-anchor="middle" font-size="9" fill="#334155">• Çini, minyatür ve mimari</text>\n  <text x="602" y="144" text-anchor="middle" font-size="9" fill="#334155">• Kopuz, dombra, komuz,</text>\n  <text x="602" y="164" text-anchor="middle" font-size="9" font-weight="bold" fill="#7e22ce">bağlama ve tar ezgileri</text>\n</svg>', '<svg viewBox="0 0 700 225" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="225" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ETKİLİ KONUŞMA SÜRECİNİN DÖRT AŞAMASI (TDE3.1 - TDE3.4)</text>\n  <rect x="18" y="46" width="155" height="156" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="95" y="68" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">1. SEÇİM VE YÖNETİM</text>\n  <text x="95" y="90" text-anchor="middle" font-size="9" fill="#334155">• Amaç, süre ve hedef</text>\n  <text x="95" y="106" text-anchor="middle" font-size="9" fill="#334155">kitleyi belirleme.</text>\n  <text x="95" y="124" text-anchor="middle" font-size="9" fill="#334155">• Hazırlıklı / hazırlıksız</text>\n  <text x="95" y="140" text-anchor="middle" font-size="9" fill="#334155">türe uygun strateji.</text>\n  <text x="95" y="160" text-anchor="middle" font-size="9" font-weight="bold" fill="#1d4ed8">• İletişim engellerini aşma.</text>\n  <rect x="187" y="46" width="155" height="156" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="264" y="68" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">2. İÇERİK VE PLAN</text>\n  <text x="264" y="90" text-anchor="middle" font-size="9" fill="#334155">• Dikkat çekici Giriş,</text>\n  <text x="264" y="106" text-anchor="middle" font-size="9" fill="#334155">Gelişme ve vurucu Sonuç.</text>\n  <text x="264" y="124" text-anchor="middle" font-size="9" fill="#334155">• Karşılaştırma, tanık</text>\n  <text x="264" y="140" text-anchor="middle" font-size="9" fill="#334155">gösterme, örneklendirme.</text>\n  <text x="264" y="160" text-anchor="middle" font-size="9" font-weight="bold" fill="#15803d">• Görsel-işitsel destek.</text>\n  <rect x="356" y="46" width="155" height="156" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="433" y="68" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#92400e">3. SUNUM VE ÜSLUP</text>\n  <text x="433" y="90" text-anchor="middle" font-size="9" fill="#334155">• Diksiyon, telaffuz,</text>\n  <text x="433" y="106" text-anchor="middle" font-size="9" fill="#334155">vurgu ve tonlama.</text>\n  <text x="433" y="124" text-anchor="middle" font-size="9" fill="#334155">• Beden dili, göz teması,</text>\n  <text x="433" y="140" text-anchor="middle" font-size="9" fill="#334155">mekân ve zaman yönetimi.</text>\n  <text x="433" y="160" text-anchor="middle" font-size="9" font-weight="bold" fill="#b45309">• Bağdaşıklık ve değerler.</text>\n  <rect x="525" y="46" width="157" height="156" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="603" y="68" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#6b21a8">4. DEĞERLENDİRME</text>\n  <text x="603" y="90" text-anchor="middle" font-size="9" fill="#334155">• Öz değerlendirme ve</text>\n  <text x="603" y="106" text-anchor="middle" font-size="9" fill="#334155">akran geri bildirimi.</text>\n  <text x="603" y="124" text-anchor="middle" font-size="9" fill="#334155">• İçerik ve dil-anlatım</text>\n  <text x="603" y="140" text-anchor="middle" font-size="9" fill="#334155">ölçütleriyle kontrol.</text>\n  <text x="603" y="160" text-anchor="middle" font-size="9" font-weight="bold" fill="#7e22ce">• Özgün konuşmacı kimliği.</text>\n</svg>', '<svg viewBox="0 0 700 225" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="225" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">CÜMLENİN ÖGELERİ ÇÖZÜMLEMESİ VE SÖZ DİZİMİ VURGUSU</text>\n  <rect x="20" y="45" width="660" height="72" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">Örnek Cümle:  "Bilge Tonyukuk,  /  Orhun Vadisi\'nde  /  Türk milletine  /  birlik bilincini  /  aşılamıştır."</text>\n  <text x="115" y="96" text-anchor="middle" font-size="10" font-weight="bold" fill="#1e40af">[Özne: Kim?]</text>\n  <text x="255" y="96" text-anchor="middle" font-size="10" font-weight="bold" fill="#166534">[Yer Tam.: Nerede?]</text>\n  <text x="395" y="96" text-anchor="middle" font-size="10" font-weight="bold" fill="#7e22ce">[Yer Tam.: Kime?]</text>\n  <text x="520" y="96" text-anchor="middle" font-size="10" font-weight="bold" fill="#dc2626">[Belirtili Nesne ★ Vurgu]</text>\n  <text x="635" y="96" text-anchor="middle" font-size="10" font-weight="bold" fill="#0f172a">[Yüklem]</text>\n  <rect x="20" y="130" width="320" height="78" rx="8" fill="#dbeafe" stroke="#2563eb" stroke-width="1.6"/>\n  <text x="180" y="150" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">CÜMLE VURGUSU KURALI</text>\n  <text x="180" y="170" text-anchor="middle" font-size="9.5" fill="#334155">• Fiil cümlesinde vurgu, yüklemden hemen önceki</text>\n  <text x="180" y="188" text-anchor="middle" font-size="9.5" fill="#334155">ögededir (Yukarıda: \'birlik bilincini\' - Belirtili Nesne).</text>\n  <rect x="360" y="130" width="320" height="78" rx="8" fill="#dcfce7" stroke="#16a34a" stroke-width="1.6"/>\n  <text x="520" y="150" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">ARA SÖZ VE CÜMLE DIŞI UNSUR</text>\n  <text x="520" y="170" text-anchor="middle" font-size="9.5" fill="#334155">• Bir ögeyi açıklayan ara söz o ögeye dâhildir;</text>\n  <text x="520" y="188" text-anchor="middle" font-size="9.5" fill="#334155">bağlaç, ünlem ve ara cümleler cümle dışı unsurdur.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
